section_3306_c_5_a_family_employment.procedure:
def apply(inputs, premises):
    applies = False
    for relation in inputs['case_family_relations']:
        if len(relation) == 3:
            owner = relation[0]
            kinship = relation[1]
            relative = relation[2]
            if owner == inputs['employee'] and relative == inputs['employer'] and (kinship in premises['excluded_employer_relations_to_employee']):
                applies = True
            if owner == inputs['employer'] and relative == inputs['employee'] and (kinship == 'spouse') and ('spouse' in premises['excluded_employer_relations_to_employee']):
                applies = True
            if owner == inputs['employer'] and relative == inputs['employee'] and (kinship == 'father' or kinship == 'mother') and ('son' in premises['excluded_employer_relations_to_employee'] or 'daughter' in premises['excluded_employer_relations_to_employee']):
                applies = True
    answer = 'Entailment' if applies else 'Contradiction'
    return {'answer': answer}
